### Program 1: Array-Based Implementation
```cpp
#include <iostream>
#include <string>
using namespace std;

struct Patient {
    int id;
    string type;
    int waitingTime;
};

void displayArray(Patient arr[], int size) {
    for (int i = 0; i < size; i++) {
        cout << "ID: " << arr[i].id << " | Type: " << arr[i].type << " | Wait: " << arr[i].waitingTime << " mins\n";
    }
}

int main() {
    // Implementation for Dataset 1, 2, and 3 using fixed-size arrays
    Patient ds1[3] = {{101, "Emergency", 45}, {102, "Consultation", 20}, {103, "Screening", 10}};
    Patient ds2[3] = {{201, "Emergency", 60}, {202, "Treatment", 35}, {203, "Consultation", 15}};
    Patient ds3[3] = {{301, "Screening", 5}, {302, "Emergency", 80}, {303, "Treatment", 40}};

    cout << "--- Dataset 1 (Array) ---\n";
displayArray(ds1, 3);
    cout << "\n--- Dataset 2 (Array) ---\n";
displayArray(ds2, 3);
    cout << "\n--- Dataset 3 (Array) ---\n";
displayArray(ds3, 3);

    return 0;
}
```

### Program 2: Singly Linked List Implementation
```cpp
#include <iostream>
#include <string>
using namespace std;

struct Node {
    int id;
    string type;
    int waitingTime;
    Node* next;
};

void insertNode(Node*& head, int id, string type, int wait) {
    Node* newNode = new Node{id, type, wait, head};
    head = newNode;
}

void displayList(Node* head) {
    Node* temp = head;
    while (temp != nullptr) {
        cout << "ID: " << temp->id << " | Type: " << temp->type << " | Wait: " << temp->waitingTime << " mins\n";
        temp = temp->next;
    }
}

int main() {
    Node* list1 = nullptr; 
    Node* list2 = nullptr;
    Node* list3 = nullptr;

    // Dataset 1
    insertNode(list1, 103, "Screening", 10);
    insertNode(list1, 102, "Consultation", 20);
    insertNode(list1, 101, "Emergency", 45);

    // Dataset 2
    insertNode(list2, 203, "Consultation", 15);
    insertNode(list2, 202, "Treatment", 35);
    insertNode(list2, 201, "Emergency", 60);

    // Dataset 3
    insertNode(list3, 303, "Treatment", 40);
    insertNode(list3, 302, "Emergency", 80);
    insertNode(list3, 301, "Screening", 5);

    cout << "--- Dataset 1 (Linked List) ---\n";
displayList(list1);
    cout << "\n--- Dataset 2 (Linked List) ---\n";
displayList(list2);
    cout << "\n--- Dataset 3 (Linked List) ---\n";
displayList(list3);

    return 0;
}
```
